
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"BookOfQueenAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
			
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.ykm!=undefined){
			
			if(gameController.mih!=parseInt(tmpMess[1])){
				
			gameController.mih=parseInt(tmpMess[1]);	
			gameController.sbg=parseInt(tmpMess[1]);	
				
			gameController.ykm.tqu("xtv", "#setText", [gameController.mer(tmpMess[1]),true])
				
			}
			
			
			
			
			
			}	
			
		}
		
